 "content": "def transform(grid):
    """Extend each non-1 marker upward as a four-cell ray: marker over three 1s."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    marker_row = next((r for r, row in enumerate(grid) if any(v not in (0, 1) for v in row)), None)
    if marker_row is None:
        return out
    for c, value in enumerate(grid[marker_row]):
        if value not in (0, 1):
            for offset in range(1, 5):
                r = marker_row - offset
                if r < 0:
                    break
                out[r][c] = value if offset == 4 else 1
    return out
